import {createAutosaver} from './autosave.js';
import {clone} from './model.js';
import {ensureQueue,addPoseTask,queueTask,startTaskFrame,linkTaskFrame,saveTaskOutput,savedOutput,restoreTaskOutput,outputMatchesFrames} from './queue.js';
export function installPoseQueue({getProject,selected,actor,mutate,selectFrame,loadProject,download,toast}){
 const panel=document.createElement('section');panel.className='pose-queue';panel.id='pose-queue';panel.innerHTML=`<h2>Pose queue</h2><p class="hint">Work through a pose, link its frames, then save an exact output ready for Codex. Ready does not install or approve artwork.</p><div class="queue-list"></div><h3 class="task-title"></h3><p class="task-brief"></p><p class="task-status" role="status"></p><div class="queue-actions"><button data-q="blank">Start blank human frame</button><button data-q="link">Link current frame</button><button data-q="restore">Resume saved output as a copy</button></div><div class="queue-frames"></div><label>Task notes<textarea class="task-notes" maxlength="2000" placeholder="What changed, facing, contact points, anything Codex should check"></textarea></label><button data-q="ready" class="primary">Save output · ready for Codex</button><button data-q="output">Download task output</button><details><summary>Add a pose task</summary><label>New task title<input class="new-title" maxlength="120"></label><label>Instructions<textarea class="new-brief" maxlength="3000"></textarea></label><button data-q="add">Add task</button></details><hr><h3>Shared project saves</h3><p class="shared-description hint">Save online to make this project and its exact task outputs available on another device and to Codex. Browser autosave continues offline.</p><button data-q="save">Save project online</button><button data-q="list">Open saved project</button><div class="saved-projects"></div><p class="cloud-status" role="status">Not saved online in this session.</p>`;
 document.querySelector('.workbench').append(panel);const reminder=document.createElement('div');reminder.className='queue-reminder';const reminderText=document.createElement('span'),open=document.createElement('button');open.textContent='Pose queue';reminder.append(reminderText,open);document.querySelector('.projectbar').after(reminder);open.onclick=()=>panel.scrollIntoView({behavior:'auto',block:'start'});
 const $=s=>panel.querySelector(s)||document.querySelector(s),action=key=>$(`[data-q="${key}"]`);let selectedTaskId='',notesSignature='',busy=false;let etags;try{etags=new Map(JSON.parse(localStorage.getItem('cat-studio-etags.v1')||'[]'));}catch{etags=new Map();}const rememberEtag=(id,etag)=>{etags.set(id,etag);try{localStorage.setItem('cat-studio-etags.v1',JSON.stringify([...etags]));}catch{}};
 const localPreview=['127.0.0.1','localhost'].includes(location.hostname);if(localPreview){action('save').textContent='Save to this workspace';$('.shared-description').textContent='This local preview saves to this computer’s project workspace. Use the hosted editor for cross-device online saves.';} const safe=fn=>{try{fn();}catch(e){toast(e.message);}};
 const task=()=>queueTask(getProject(),selectedTaskId||ensureQueue(getProject()).selectedId);
 const navigate=f=>{if(f)selectFrame(f.id);};
 action('blank').onclick=()=>safe(()=>{let f;mutate(()=>{f=startTaskFrame(getProject(),task().id,actor());});navigate(f);document.querySelector('.stage').scrollIntoView({block:'center'});});
 action('link').onclick=()=>safe(()=>mutate(()=>linkTaskFrame(getProject(),task().id,selected().id)));
 action('restore').onclick=()=>safe(()=>{let f;mutate(()=>{f=restoreTaskOutput(getProject(),task().id);});navigate(f);});
 $('.task-notes').onchange=()=>safe(()=>mutate(()=>{task().notes=$('.task-notes').value;}));
 action('ready').onclick=()=>safe(()=>{mutate(()=>saveTaskOutput(getProject(),task().id,$('.task-notes').value,actor()));saveOnline();});
 action('output').onclick=()=>safe(()=>download('cat-pose-'+task().id+'.json',JSON.stringify(savedOutput(getProject(),task().id),null,2)));
 action('add').onclick=()=>safe(()=>{mutate(()=>{const t=addPoseTask(getProject(),{title:$('.new-title').value,instructions:$('.new-brief').value});ensureQueue(getProject()).selectedId=t.id;selectedTaskId=t.id;});$('.new-title').value='';$('.new-brief').value='';});
 async function api(path,options={}){const response=await fetch('/api/'+path,{...options,headers:{'Content-Type':'application/json',...options.headers}});let value;try{value=await response.json();}catch{throw Error('Shared saves are unavailable here. Your browser copy is safe; download the project or task output.');}if(!response.ok){const error=Error(response.status===409?'A newer saved version exists. Open saved to review it; your browser copy is retained.':value.error||'Shared save failed.');error.status=response.status;throw error;}return {value,etag:response.headers.get('etag')};}
 const OUTBOX='cat-studio-autosave-outbox.v1',states=new Map();let initial=[];try{initial=JSON.parse(localStorage.getItem(OUTBOX)||'[]');}catch{}
 function refreshStatus(){const id=getProject()?.projectId,state=states.get(id);const message=state?.message||'Autosave on · '+(localPreview?'this workspace':'private online storage');document.querySelector('#save-status').textContent=message;const badge=document.querySelector('#autosave-summary');if(badge)badge.textContent=message;}
 const saver=createAutosaver({initial,write:async p=>{
  if(!etags.has(p.projectId)){try{const existing=await api('projects/'+p.projectId);if(JSON.stringify(existing.value.project)!==JSON.stringify(p)){const e=Error('Saved sequence already exists. Open saved to reconcile it; your local version is retained.');e.status=409;throw e;}rememberEtag(p.projectId,existing.etag);return;}catch(e){if(e.status!==404)throw e;}}
  const result=await api('projects/'+p.projectId,{method:'PUT',headers:etags.has(p.projectId)?{'If-Match':etags.get(p.projectId)}:{'If-None-Match':'*'},body:JSON.stringify(p)});rememberEtag(p.projectId,result.etag);
 },persist:pending=>{try{localStorage.setItem(OUTBOX,JSON.stringify(pending));}catch{toast('Storage is full. Export a backup to keep this draft.');}},changed:(id,state,error)=>{
  if(state==='saved')window.dispatchEvent(new CustomEvent('studio-asset-saved'));
  const message={pending:'Saving soon…',saving:'Saving…',saved:localPreview?'Autosaved to workspace':'Autosaved online',offline:'Saved in browser · retry when connected',conflict:'Saved in browser · newer server version exists'}[state];states.set(id,{state,message});if(error)$('.cloud-status').textContent=error;else $('.cloud-status').textContent=message;refreshStatus();
 }});
 async function saveOnline(){saver.queue(getProject());await saver.flush();}
 async function hydrate(book){
  const adopted=new Set();try{const {value}=await api('projects');await Promise.all(value.projects.map(async item=>{
   const result=await api('projects/'+item.projectId),remote=result.value.project,local=book[item.projectId],known=etags.get(item.projectId);
   if(saver.hasPending(item.projectId))return;
   if(local&&known===result.etag){saver.acknowledge(remote);return;}
   if(local&&JSON.stringify(local.project)!==JSON.stringify(remote)){
    const archived=clone(local.project);archived.projectId='browser-backup-'+crypto.randomUUID();archived.name=(archived.name+' · earlier browser copy').slice(0,120);archived.archived=true;archived.archivedFrom=item.projectId;book[archived.projectId]={project:archived,index:local.index};
   }
   book[item.projectId]={project:clone(remote),index:local?.index||0};rememberEtag(item.projectId,result.etag);saver.loaded(remote);adopted.add(item.projectId);
  }));}catch(e){$('.cloud-status').textContent='Browser drafts retained. '+e.message;}
  return adopted;
 }
 window.addEventListener('online',()=>saver.flush());window.addEventListener('pagehide',()=>saver.flush());document.addEventListener('visibilitychange',()=>{if(document.hidden)saver.flush();});
 action('save').onclick=()=>saveOnline();
 action('list').onclick=async()=>{try{const {value}=await api('projects');$('.saved-projects').replaceChildren();if(!value.projects.length)$('.cloud-status').textContent='No shared projects yet. Save this project online first.';for(const p of value.projects.filter(p=>!p.deletedAt)){const b=document.createElement('button');b.textContent=`${p.name} · ${p.ready} ready · ${new Date(p.savedAt).toLocaleString()}`;b.onclick=async()=>{try{const result=await api('projects/'+p.projectId);if(loadProject(result.value.project)!==false){rememberEtag(p.projectId,result.etag);saver.loaded(result.value.project);selectedTaskId='';$('.cloud-status').textContent='Opened saved project.';render();}}catch(e){toast(e.message);}};$('.saved-projects').append(b);}}catch(e){$('.cloud-status').textContent=e.message;}};
 function render(){refreshStatus();const p=getProject();if(!p)return;const q=ensureQueue(p);if(!q.tasks.some(t=>t.id===selectedTaskId))selectedTaskId=q.tasks.some(t=>t.id===q.selectedId)?q.selectedId:q.tasks[0]?.id;if(!selectedTaskId)return;const t=task(),remaining=q.tasks.filter(t=>t.status!=='ready').length;const vertical=q.tasks.filter(t=>['vertical-up','vertical-down'].includes(t.id)&&t.status!=='ready');reminderText.textContent=vertical.length?'Reminder: author '+vertical.map(t=>t.title.toLowerCase()).join(' and ')+' poses.':`${remaining} pose tasks remaining · ${q.tasks.filter(t=>t.status==='ready').length} ready for Codex.`;
  $('.queue-list').replaceChildren();for(const item of q.tasks){const b=document.createElement('button');b.className=item.id===t.id?'active':'';b.textContent=`${item.title} · ${item.status==='ready'?'Ready for Codex':item.status==='in-progress'?'In progress':'To do'}${item.priority==='high'?' · Priority':''}`;b.onclick=()=>safe(()=>mutate(()=>{selectedTaskId=item.id;q.selectedId=item.id;}));$('.queue-list').append(b);}
  $('.task-title').textContent=t.title;$('.task-brief').textContent=t.instructions;const o=t.outputs.at(-1);$('.task-status').textContent=o?`Saved output: ${o.id} · ${new Date(o.savedAt).toLocaleString()}${outputMatchesFrames(p,t)?' · matches linked frames':' · exact snapshot retained; current frames differ or are not loaded'}`:'No saved output yet.';const signature=t.id+'\n'+t.notes;if(signature!==notesSignature&&document.activeElement!==$('.task-notes')){$('.task-notes').value=t.notes;notesSignature=signature;}
  $('.queue-frames').replaceChildren();for(const fid of t.frameIds){const f=p.frames.find(f=>f.id===fid),row=document.createElement('div'),b=document.createElement('button');b.textContent=f?`${f.name} · ${f.origin}`:'Frame not loaded · use saved output';b.disabled=!f;b.onclick=()=>navigate(f);const remove=document.createElement('button');remove.textContent='Unlink';remove.onclick=()=>safe(()=>mutate(()=>{t.frameIds=t.frameIds.filter(id=>id!==fid);t.status='in-progress';}));row.append(b,remove);$('.queue-frames').append(row);}action('output').disabled=action('restore').disabled=!o;action('ready').disabled=actor()!=='human';
 }
 const tools=[{name:'get_pose_queue',description:'Read the project pose queue, human authoring briefs, linked frame IDs and exact saved task outputs. Ready means saved for Codex, not approved or installed.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({content:[{type:'text',text:JSON.stringify({projectId:getProject().projectId,name:getProject().name,queue:clone(ensureQueue(getProject()))})}]})},{name:'get_pose_output',description:'Read an exact saved pose output and its per-frame provenance from this project.',inputSchema:{type:'object',properties:{taskId:{type:'string'},outputId:{type:'string'}},required:['taskId'],additionalProperties:false},annotations:{readOnlyHint:true},execute:input=>({content:[{type:'text',text:JSON.stringify(savedOutput(getProject(),input.taskId,input.outputId))}]})}];
 return {render,tools,autosave:p=>saver.queue(p),flush:()=>saver.flush(),hydrate,refreshStatus,resume:()=>saver.flush()};
}
